class TrackingItemModel {final String status,description,date,location; TrackingItemModel({required this.status,required this.description,required this.date,required this.location}); factory TrackingItemModel.fromJson(Map<String,dynamic> j)=>TrackingItemModel(status:(j['status']??'-').toString(),description:(j['description']??'-').toString(),date:(j['date']??'-').toString(),location:(j['location']??'-').toString());}
class TrackingModel {final List<TrackingItemModel> items; TrackingModel({required this.items}); factory TrackingModel.fromJson(dynamic d){final l=(d is List?d:(d is Map<String,dynamic>?d['items']:null)) as List? ?? []; return TrackingModel(items:l.whereType<Map<String,dynamic>>().map(TrackingItemModel.fromJson).toList());}}
